/**
 * Hashing and verification, including the bcrypt hashes imported from the team's previous app
 * (decision 200).
 *
 * The bcrypt fixtures come in two kinds on purpose. Most are generated by the library inside the
 * test, which proves the round trip; one is a **hard-coded** `$2a$10$` string whose password is
 * written beside it, which proves that a future change of library — or of its options — has not
 * quietly stopped understanding the bytes already sitting in the database. Only the second kind
 * can fail for the reason that would actually lock a teammate out.
 */

import { hash as bcryptHash } from "@node-rs/bcrypt";
import { describe, expect, it, vi } from "vitest";

vi.mock("server-only", () => ({}));

const { hashPassword, isBcryptHash, verifyPassword } = await import("./password");

/**
 * A real bcrypt hash of `PINNED_PASSWORD`, of the `$2a$10$` shape the previous app's database
 * holds, written out rather than generated. Do not regenerate it: that would make this test pass
 * by construction and remove the only check that stored data is still readable.
 */
const PINNED_HASH = "$2a$10$/n35uAv5snu7stW4bYImEuvmZYdPPhOMluPIc7.y9Bis1mORJB5he";
const PINNED_PASSWORD = "allez-les-7-orteils";

describe("isBcryptHash", () => {
  it("recognises the three prefixes an imported hash can carry", () => {
    expect(isBcryptHash("$2a$10$0123456789012345678901")).toBe(true);
    expect(isBcryptHash("$2b$10$0123456789012345678901")).toBe(true);
    expect(isBcryptHash("$2y$10$0123456789012345678901")).toBe(true);
  });

  it("claims nothing about an argon2 hash, or about anything it cannot name", () => {
    expect(isBcryptHash("$argon2id$v=19$m=19456,t=2,p=1$abc$def")).toBe(false);
    expect(isBcryptHash("$2x$10$0123456789012345678901")).toBe(false);
    expect(isBcryptHash("")).toBe(false);
    expect(isBcryptHash("pas un hash")).toBe(false);
  });
});

describe("hashPassword", () => {
  it("only ever produces argon2id", async () => {
    const stored = await hashPassword("un-mot-de-passe");
    expect(stored.startsWith("$argon2id$")).toBe(true);
  });

  it("salts, so the same password twice is two different hashes", async () => {
    const [first, second] = await Promise.all([hashPassword("idem"), hashPassword("idem")]);
    expect(first).not.toEqual(second);
  });
});

describe("verifyPassword, against an argon2id hash", () => {
  it("accepts the right password and asks for no upgrade", async () => {
    const stored = await hashPassword("le-bon-mot-de-passe");
    expect(await verifyPassword(stored, "le-bon-mot-de-passe")).toEqual({
      ok: true,
      needsUpgrade: false,
    });
  });

  it("refuses the wrong one", async () => {
    const stored = await hashPassword("le-bon-mot-de-passe");
    expect(await verifyPassword(stored, "le-mauvais")).toEqual({
      ok: false,
      needsUpgrade: false,
    });
  });
});

describe("verifyPassword, against a bcrypt hash", () => {
  it("accepts the right password and asks for an upgrade", async () => {
    const stored = await bcryptHash(PINNED_PASSWORD, { cost: 6, version: "2a" });
    expect(stored.startsWith("$2a$06$")).toBe(true);
    expect(await verifyPassword(stored, PINNED_PASSWORD)).toEqual({
      ok: true,
      needsUpgrade: true,
    });
  });

  it("refuses the wrong password, and asks for no upgrade when it does", async () => {
    const stored = await bcryptHash(PINNED_PASSWORD, { cost: 6, version: "2a" });
    expect(await verifyPassword(stored, "pas-le-bon")).toEqual({
      ok: false,
      needsUpgrade: false,
    });
  });

  it("reads the two costs the previous app's database actually holds", async () => {
    for (const cost of [6, 10]) {
      const stored = await bcryptHash(PINNED_PASSWORD, { cost, version: "2a" });
      expect(stored).toHaveLength(60);
      expect(await verifyPassword(stored, PINNED_PASSWORD)).toEqual({
        ok: true,
        needsUpgrade: true,
      });
    }
  });

  it("still understands a hard-coded $2a$10$ hash of a known password", async () => {
    expect(await verifyPassword(PINNED_HASH, PINNED_PASSWORD)).toEqual({
      ok: true,
      needsUpgrade: true,
    });
    expect(await verifyPassword(PINNED_HASH, "presque-le-bon")).toEqual({
      ok: false,
      needsUpgrade: false,
    });
  });

  it("reads a $2b$ and a $2y$ hash too", async () => {
    for (const version of ["2b", "2y"] as const) {
      const stored = await bcryptHash(PINNED_PASSWORD, { cost: 6, version });
      expect(stored.startsWith(`$${version}$06$`)).toBe(true);
      expect(await verifyPassword(stored, PINNED_PASSWORD)).toEqual({
        ok: true,
        needsUpgrade: true,
      });
    }
  });
});

describe("verifyPassword, against something that is not a hash", () => {
  it("reads every malformed stored value as a wrong password, and never throws", async () => {
    const stored = [
      "",
      "   ",
      "n'importe quoi",
      "$2a$", // the prefix and nothing else
      PINNED_HASH.slice(0, 30), // a truncated bcrypt hash
      `${PINNED_HASH}xx`, // and one with trailing rubbish
      "$argon2id$v=19$m=19456,t=2,p=1$incomplet",
      "$2a$10$" + "\u0000".repeat(53), // not valid bcrypt base64
    ];

    for (const value of stored) {
      await expect(verifyPassword(value, PINNED_PASSWORD)).resolves.toEqual({
        ok: false,
        needsUpgrade: false,
      });
    }
  });

  it("reads an empty password as wrong rather than as a match", async () => {
    expect(await verifyPassword(PINNED_HASH, "")).toEqual({ ok: false, needsUpgrade: false });
    const argon = await hashPassword("quelque-chose");
    expect(await verifyPassword(argon, "")).toEqual({ ok: false, needsUpgrade: false });
  });
});
